11	
12	const name = 'meterwatch';
13	
14	const help = `${name}
15	
16	建筑能耗监测:本地累计电表读数导入与消耗核查。
17	
18	Usage:
19	  node app.ts                       显示本帮助
20	  node app.ts --help | -h           显示本帮助
21	  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
22	  node app.ts readings [筛选...]    查询读数、区间与消耗
23	  node app.ts daily --from <iso> --to <iso> [--device <id>...] [--tz <时区>]
24	                                    按当地自然日核查能耗的只读日报(默认 UTC 分日)
25	  node app.ts rule create --id <id> (--device <设备> | --group <分组>) --threshold <kWh> [--tz <时区>]
26	                                    创建每日能耗阈值告警规则(设备或分组,时区省略为 UTC)
27	  node app.ts rule list             查看全部告警规则
28	  node app.ts evaluate --rule <id> --from <日期> --to <日期>
29	                                    评估规则在连续完整当地日期(按规则时区)上的超限情况
30	  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
31	                                    查询规则的告警历史(只读)
32	  node app.ts ack <告警标识>         确认告警
33	  node app.ts group configure --id <id> --at <iso> --device <id>...
34	                                    配置分组成员版本(首次配置即建立分组)
35	  node app.ts group history --id <id>
36	                                    查看分组成员版本历史(只读)
37	  node app.ts group daily --id <id> --from <iso> --to <iso> [--tz <时区>]
38	                                    按当时生效成员的分组能耗日报(只读,默认 UTC 分日)
39	  node app.ts correct --request <id> --item --device <设备> --at <iso> --expect <kWh> --set <kWh>
40	                                    [--item --device ... --at ... --expect ... --set ...]...
41	                                    批量修正已存读数的累计值(整批成功或整批拒绝)
42	  node app.ts undo --request <id> --target <修正请求标识>
43	                                    整批撤销一次已成功修正(恢复实际改变过的读数)
44	  node app.ts corrections             查看修正与撤销历史(只读)
45	  node app.ts backup <快照文件>       导出全库快照(快照文件须位于数据目录之外,已存在则拒绝)
46	  node app.ts restore <快照文件>      从快照整库恢复(三个业务存储作为一次提交整体替换)
47	
48	备份与恢复(backup / restore):
49	  backup 把当前数据目录的三个业务存储(读数与修正/撤销历史、告警规则与历史、
50	  分组成员版本)连同后续编号状态完整导出为一个快照文件,任意大数精确保留;
51	  快照带格式版本与 SHA-256 完整性校验。快照文件必须位于数据目录之外,已存在
52	  的输出文件拒绝覆盖;备份只读取业务数据,不改写。restore 不解析当前库(可用于
53	  当前存储已损坏的目录),先校验快照的版本、完整性与三个存储的结构和关联
54	  (全库重复读数身份、修正项引用缺失读数、撤销引用缺失修正、成员或规则目标
55	  不存在、告警引用缺失规则,任一问题指出原因并拒绝),再把三个业务存储作为
56	  一次提交整体替换:成功后业务状态完全等于快照,快照为空的部分清除原数据,
57	  快照之后新增的读数、请求和告警不保留,目录内其他文件保持不变,不自动评估
58	  或重新生成历史。读写或重命名失败返回 1 并回退到恢复前文件内容与存在状态。
59	
60	进程在准备、文件替换、失败回滚或启动自恢复中被终止的处理:
61	  任一命令(含无参数、--help/-h 与非法参数入口)再次启动,都先取得数据目录
62	  操作权并续接未完成恢复,然后才执行查询或写入。恢复日志用阶段记录进度:
63	  尚未进入失败回滚的中断可收敛为完整旧库或完整快照;已经进入失败回滚后
64	  只能继续还原完整旧库,不能改为前滚;自恢复再次中断仍可续接。回滚中已
65	  还原的旧文件不会被误删,原本缺失的业务文件恢复为缺失(不把事务造成的
66	  缺文件当成空库)。无法可靠判定或完成一致恢复时返回 1:不输出正常业务
67	  结果、不做业务写入,也不删除仍可用于恢复的材料(restore.journal 与
68	  *.restore-old / *.restore-new),修好底层读写问题后再运行任一命令即可续接。
69	
70	目录操作权(排他锁,按数据目录隔离):
71	  每个命令从取得目录操作权起先协调再读写。同目录被其他存活进程占用时
72	  明确拒绝并返回 1,不读写业务存储,也不清理对方的事务材料;属主退出后
73	  可安全接管其未完成恢复;不同数据目录互不阻塞。备份、恢复与启动自恢复
74	  期间,其他命令同样受此限制。锁文件为数据目录内的 meterwatch.lock。
75	
76	故障处理简述:
77	  - 命令报 "locked by another live meterwatch process":等占用进程结束,
78	    或确认其已退出后删除残留的 meterwatch.lock 再重试。
79	  - 报 "cannot complete interrupted restore ... materials were kept":
80	    保留目录内 restore.journal 与 *.restore-old/*.restore-new,排除磁盘
81	    只读/权限/空间问题后,再运行任意命令完成续接;切勿手工删改这些文件。
82	  - 报 restore journal 不可读或无效:目录处于无法自动判定的状态,需用已知
83	    完好的快照手工恢复,不要直接在可能混合的目录上继续业务操作。
84	
85	筛选(readings):
86	  --device <id>     只显示指定设备(可重复使用,区分大小写)
87	  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
88	  --to <iso8601>    结束时刻(不含)
89	  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
90	  (如 +08:00);起点不早于终点时拒绝查询。
91	
92	日报(daily):
93	  --from <iso8601>  起始时刻(含),必填
94	  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
95	  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
96	  --tz <时区>       分日时区(IANA 名,如 Asia/Shanghai);省略时按 UTC
97	  日期按分日时区的当地零点划分,首尾日期只统计与查询范围重叠的部分。
98	  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
99	  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
100	  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
101	  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
102	  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
103	  孤立读数时段为未知,不外推。每天输出估算消耗与有效/异常/未知覆盖秒数
104	  (三者之和等于该天实际统计的各 UTC 时段总秒数),并标明所用时区与各
105	  UTC 时段;存在未知或异常覆盖时日报标记为不完整。日报只读,不写入数据。
106	
107	分日时区(--tz,daily 与 group daily 可选):
108	  接受运行环境支持的 IANA 时区名(如 Asia/Shanghai、America/New_York);
109	  未知时区名为参数错误,返回 2。时区只决定分日,不重新解释输入时刻或
110	  已存读数。日界线按实际时刻的当地日期归属计算,不按固定 86400 秒或
111	  全年固定偏移推算:夏令时前拨跳过的当天更短(跳过的小时不存在,不补
112	  为未知),回拨当天更长(重复小时按各自实际时刻完整计入);同一当地
113	  日期的不连续时段合并统计、分别列出;没有实际时段的当地日期不生成
114	  日报。日界线不重置分摊起点,拆开查询再相加与整段一致。
115	
116	分组(group configure / history / daily):
117	  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
118	  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
119	  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
120	  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
121	  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
122	  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
123	  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
124	  与 --to(不含)必填且起点必须更早,按分日时区的自然日切分(--tz 可选,
125	  默认 UTC,口径见上文"分日时区"),按当时生效成员计算,首个版本生效前
126	  记为未知;每个时段只有全部生效成员均处于非下降读数
127	  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
128	  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
129	  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
130	  切换均不重置分摊起点,拆开查询相加一致。每天显示生效成员及其时段、估算
131	  消耗与有效/异常/未知秒数(三者之和等于当天查询时长);有异常或未知标为
132	  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。
133	
134	修正与撤销(correct / undo / corrections):
135	  correct 一次提交指定非空请求标识(--request,去首尾空白、区分大小写,在
136	  数据目录内唯一)及至少一个 --item 修正项;每项 --device、--at、--expect、
137	  --set 各恰好一个,给出设备、实际时刻(秒精度 ISO8601 带 Z 或数字时区
138	  偏移)、预期原读数和替换读数(均为非负、最多三位小数 kWh,任意大数精确)。
139	  只修改已有读数的累计值,不新增或删除读数;同批同一读数身份(设备+实际
140	  时刻)只允许一项;替换值可等于原值,但仍须核验预期原值。首次提交逐项把
141	  预期原值与操作前已存值精确比较,全部匹配才整体替换,成功报告请求标识与
142	  实际改变数;任一项身份不存在或原值不符均指出原因、整批拒绝,不改变其他
143	  项,也不占用请求标识(失败后可修改内容用同一标识重新提交)。读数替换与
144	  请求成功记录同时持久化,写入失败保留操作前全部状态。同标识、同修正内容
145	  重放直接返回原成功结果,不重新校验当前读数、不再次替换(即使这些读数
146	  后来又被其他请求修正,或本修正后来被撤销);修正项顺序、等价时区及等价
147	  十进制写法不影响内容等价性;同标识异内容报冲突且保持状态。
148	  undo 一次提交指定非空撤销请求标识(--request)及目标修正请求标识
149	  (--target),整批撤销一次已成功修正,不允许挑选部分项;目标只能是成功
150	  修正,不能是撤销请求,未知或已撤销目标报错。撤销与修正请求共用唯一标识
151	  空间,成功标识绑定操作类型和内容。首次撤销只恢复目标中实际改变过的读数,
152	  将其还原为该修正记录的原值,不新增或删除读数;每个待恢复身份必须存在、
153	  当前值精确等于原替换值,且没有后来尚未撤销、实际改变过该读数的修正
154	  (后来改回相同数值也不能绕过来源检查,相关后续修正先撤销后才能再撤销
155	  较早请求)。同值项不恢复、不阻塞;全部为同值项的目标仍可成功撤销,恢复
156	  数为零。任一项不满足条件指出身份和原因、整次拒绝,不占用撤销标识。同
157	  撤销标识、同目标重放返回原成功结果,不重新核验、不重复恢复;同标识异
158	  目标或跨操作类型复用标识均报冲突。读数恢复与撤销成功记录同时原子持久化,
159	  重启后状态与来源判断一致。成功报告撤销请求、目标和恢复数,原修正内容
160	  保留并标记已撤销。corrections 按成功提交顺序显示各修正请求及各项设备、
161	  时刻、原值和替换值,另按成功发生顺序显示撤销请求与目标关系,只读。
162	  修正与撤销后 readings、daily、group daily 与 alerts 的当前消耗按新相邻
163	  区间重算;分组成员、规则与告警记录不变,检测状态仍需显式 evaluate 更新;
164	  后续 import 按当前读数判重与冲突,并保留修正与撤销历史。
165	
166	告警规则(rule / evaluate / alerts / ack):
167	  规则标识非空且在设备与分组两类规则间唯一(去首尾空白、区分大小写);用
168	  --device 绑定一个已有存储读数的设备,或用 --group 绑定一个已有分组(二者
169	  恰好其一);设备与分组即使同名也是不同目标,列表与历史均显示目标类型。
170	  阈值非负、最多三位小数 kWh;目标、阈值与时区创建后固定,分组规则绑定分组
171	  标识、不冻结创建时成员。--tz 可选,接受运行环境支持的 IANA 时区名(如
172	  Asia/Shanghai、America/New_York),省略为 UTC(与显式 UTC 等价);时区按
173	  运行环境解析后的规范名存储与比较,未知时区名为参数错误,返回 2。相同标识、
174	  同目标类型、同目标标识、等价阈值及同时区重试成功且不重复创建,任一不同
175	  即报冲突。
176	  evaluate 与 alerts 的 --from/--to 为 YYYY-MM-DD 的当地日期(按规则时区
177	  解释),起日含、止日不含,起日必须更早。每个日期统计归属该日期的全部实际
178	  UTC 时段,不把当地午夜套用固定偏移:夏令时短日不补未知,回拨重复小时完整
179	  计入,日期回退的不连续时段合并为同一天、一次评估只作一次判定;整日被跳过
180	  的日期标明跳过,不判定、不创建也不恢复告警。设备规则评估口径与 daily 相同;
181	  分组规则与 group daily 的联合覆盖口径相同:每天按当时生效的成员版本计算,
182	  允许日内切换,首个版本生效前为未知,任一成员下降为异常,否则任一成员未知
183	  为未知;成员切换不重置各设备原读数区间的分摊起点。仅全天有效覆盖的日期
184	  可判定,消耗严格大于阈值才超限(等于为正常),零增长有效;有未知或下降
185	  覆盖的日期不可判定,不触发也不恢复。每个规则每个日期独立跟踪:首次超限
186	  创建带全局唯一标识的未确认告警,重复超限保留原标识;完整评估正常才记录
187	  恢复;恢复后再超限创建新的未确认告警,旧记录保留,原确认不转移。批量日期
188	  评估要么全部提交要么不提交。
189	  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
190	  不改变超限或恢复状态。alerts 按规则和当地日期升序展示当前计算的消耗或不
191	  可判定原因、实际 UTC 时段及有效/异常/未知秒数、各次告警的标识、检测状态、
192	  确认状态及按发生顺序排列的触发/恢复/确认事件(触发、恢复时的消耗为当时
193	  记录,不随后续数据改写);省略日期范围时展示有告警记录的全部日期;查询
194	  只读,不会隐式恢复。导入读数或补录成员版本都不自动评估,需显式重评才更新
195	  检测状态。规则时区与历史重启后保留;没有时区的旧规则按 UTC 使用,原告警
196	  标识、日期、状态和事件顺序保留。
197	
198	CSV 格式:
199	  表头: ${CSV_HEADER}
200	  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
201	  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
202	  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
203	           范围,任意大的十进制值都精确保存,如 9007199254740.991)
204	  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
205	  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。
206	
207	数值精度:
208	  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
209	  和显示全程精确,输出固定三位小数,不使用科学计数法。
210	  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
211	  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
212	  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。
213	
214	数据位置:
215	  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json;
216	           读数与修正、撤销历史同文件保存,旧版无修正与撤销历史的文件可直接使用)
217	  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
218	  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)
219	
220	退出码: 0 成功;1 数据或读写错误;2 参数错误`;
221	
222	function usageError(message: string): number {
223	  console.error(`${name}: ${message}`);
224	  console.error(`用法见 'node app.ts --help'`);
225	  return 2;
226	}
227	
228	interface ParsedOptions {
229	  devices: string[];
230	  from?: number;
231	  to?: number;
232	  tz?: string;
233	}
234	
235	/** 解析 --device/--from/--to(及允许时的 --tz)选项;出错返回错误消息字符串。 */
236	function parseOptions(rest: string[], allowTz = false): ParsedOptions | string {
237	  const devices: string[] = [];
238	  let from: number | undefined;
239	  let to: number | undefined;
240	  let tz: string | undefined;
241	  for (let i = 0; i < rest.length; i++) {
242	    let opt = rest[i];
243	    let value: string | undefined;
244	    const eq = opt.indexOf('=');
245	    if (opt.startsWith('--') && eq !== -1) {
246	      value = opt.slice(eq + 1);
247	      opt = opt.slice(0, eq);
248	    } else if (opt.startsWith('--')) {
249	      value = rest[i + 1];
250	      if (value === undefined) return `选项 '${opt}' 缺少值`;
251	      i++;
252	    } else {
253	      return `无法识别的参数 '${opt}'`;
254	    }
255	    if (opt === '--device') {
256	      if (value.trim() === '') return "'--device' 的值不能为空";
257	      devices.push(value);
258	    } else if (opt === '--from' || opt === '--to') {
259	      const ts = parseIso8601(value.trim());
260	      if (ts === null) {
261	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
262	      }
263	      if (opt === '--from') from = ts;
264	      else to = ts;
265	    } else if (opt === '--tz' && allowTz) {
266	      tz = value.trim();
267	      if (tz === '') return "'--tz' 的值不能为空";
268	    } else {
269	      return `无法识别的选项 '${opt}'`;
270	    }
271	  }
272	  return { devices, from, to, tz };
273	}
274	
275	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
276	function checkTz(tz: string): string | null {
277	  if (loadTimezone(tz) === null) {
278	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
279	  }
280	  return null;
281	}
282	
283	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
284	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
285	  const out = new Map<string, string[]>();
286	  for (let i = 0; i < rest.length; i++) {
287	    let opt = rest[i];
288	    let value: string | undefined;
289	    const eq = opt.indexOf('=');
290	    if (opt.startsWith('--') && eq !== -1) {
291	      value = opt.slice(eq + 1);
292	      opt = opt.slice(0, eq);
293	    } else if (opt.startsWith('--')) {
294	      value = rest[i + 1];
295	      if (value === undefined) return `选项 '${opt}' 缺少值`;
296	      i++;
297	    } else {
298	      return `无法识别的参数 '${opt}'`;
299	    }
300	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
301	    const list = out.get(opt);
302	    if (list) list.push(value);
303	    else out.set(opt, [value]);
304	  }
305	  return out;
306	}
307	
308	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
309	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
310	  const list = flags.get(name);
311	  if (!list || list.length !== 1) return null;
312	  return list[0];
313	}
314	
315	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
316	function dateFlag(value: string, label: string): { date: string } | string {
317	  const v = value.trim();
318	  if (parseUtcDate(v) === null) {
319	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
320	  }
321	  return { date: v };
322	}
323	
324	function cmdRule(rest: string[]): number {
325	  const [sub, ...subrest] = rest;
326	  if (sub === 'list') {
327	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
328	    return cmdRuleList();
329	  }
330	  if (sub === 'create') {
331	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz']);
332	    if (typeof flags === 'string') return usageError(flags);
333	    const idRaw = oneFlag(flags, '--id');
334	    const deviceList = flags.get('--device');
335	    const groupList = flags.get('--group');
336	    const thresholdRaw = oneFlag(flags, '--threshold');
337	    const tzList = flags.get('--tz');
338	    if (idRaw === null || thresholdRaw === null) {
339	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
340	    }
341	    if (tzList !== undefined && tzList.length !== 1) {
342	      return usageError("'rule create' 的 --tz 只能出现一次");
343	    }
344	    const hasDevice = deviceList !== undefined;
345	    const hasGroup = groupList !== undefined;
346	    if (hasDevice === hasGroup) {
347	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
348	    }
349	    if ((deviceList !== undefined && deviceList.length !== 1) ||
350	      (groupList !== undefined && groupList.length !== 1)) {
351	      return usageError("'rule create' 的目标选项只能出现一次");
352	    }
353	    const id = idRaw.trim();
354	    if (id === '') return usageError('规则标识不能为空');
355	    const thresholdMilli = parseKwh(thresholdRaw.trim());
356	    if (thresholdMilli === null) {
357	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
358	    }
359	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
360	    let tz = 'UTC';
361	    if (tzList !== undefined) {
362	      const tzRaw = tzList[0].trim();
363	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
364	      const canonical = canonicalTimezone(tzRaw);
365	      if (canonical === null) {
366	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
367	      }
368	      tz = canonical;
369	    }
370	    if (hasDevice) {
371	      const device = (deviceList as string[])[0].trim();
372	      if (device === '') return usageError("'--device' 的值不能为空");
373	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz });
374	    }
375	    const group = (groupList as string[])[0].trim();
376	    if (group === '') return usageError("'--group' 的值不能为空");
377	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz });
378	  }
379	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
380	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
381	}
382	
383	function cmdEvaluateEntry(rest: string[]): number {
384	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
385	  if (typeof flags === 'string') return usageError(flags);
386	  const ruleRaw = oneFlag(flags, '--rule');
387	  const fromRaw = oneFlag(flags, '--from');
388	  const toRaw = oneFlag(flags, '--to');
389	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
390	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
391	  }
392	  const ruleId = ruleRaw.trim();
393	  if (ruleId === '') return usageError('规则标识不能为空');
394	  const from = dateFlag(fromRaw, '起始日期');
395	  if (typeof from === 'string') return usageError(from);
396	  const to = dateFlag(toRaw, '结束日期');
397	  if (typeof to === 'string') return usageError(to);
398	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
399	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
400	}
401	
402	function cmdAlertsEntry(rest: string[]): number {
403	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
404	  if (typeof flags === 'string') return usageError(flags);
405	  const ruleRaw = oneFlag(flags, '--rule');
406	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
407	  const ruleId = ruleRaw.trim();
408	  if (ruleId === '') return usageError('规则标识不能为空');
409	  const fromList = flags.get('--from');
410	  const toList = flags.get('--to');
411	  if ((fromList !== undefined) !== (toList !== undefined)) {
412	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
413	  }
414	  let from: string | undefined;
415	  let to: string | undefined;
416	  if (fromList !== undefined) {
417	    const fromRaw = oneFlag(flags, '--from');
418	    const toRaw = oneFlag(flags, '--to');
419	    if (fromRaw === null || toRaw === null) {
420	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
421	    }
422	    const fromParsed = dateFlag(fromRaw, '起始日期');
423	    if (typeof fromParsed === 'string') return usageError(fromParsed);
424	    const toParsed = dateFlag(toRaw, '结束日期');
425	    if (typeof toParsed === 'string') return usageError(toParsed);
426	    if (fromParsed.date >= toParsed.date) return usageError('查询起日必须早于止日(--from < --to)');
427	    from = fromParsed.date;
428	    to = toParsed.date;
429	  }
430	  return cmdAlerts({ ruleId, from, to });
431	}
432	
433	function cmdGroup(rest: string[]): number {
434	  const [sub, ...subrest] = rest;
435	  if (sub === 'configure') {
436	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
437	    if (typeof flags === 'string') return usageError(flags);
438	    const idRaw = oneFlag(flags, '--id');
439	    const atRaw = oneFlag(flags, '--at');
440	    const deviceList = flags.get('--device') ?? [];
441	    if (idRaw === null || atRaw === null) {
442	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
443	    }
444	    if (deviceList.length === 0) {
445	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
446	    }
447	    const id = idRaw.trim();
448	    if (id === '') return usageError('分组标识不能为空');
449	    const at = parseIso8601(atRaw.trim());
450	    if (at === null) {
451	      return usageError(
452	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
453	      );
454	    }
455	    const members: string[] = [];
456	    for (const d of deviceList) {
457	      const m = d.trim();
458	      if (m === '') return usageError("'--device' 的值不能为空");
459	      members.push(m);
460	    }
461	    return cmdGroupConfigure({ id, at, members });
462	  }
463	  if (sub === 'history') {
464	    const flags = parseFlags(subrest, ['--id']);
465	    if (typeof flags === 'string') return usageError(flags);
466	    const idRaw = oneFlag(flags, '--id');
467	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
468	    const id = idRaw.trim();
469	    if (id === '') return usageError('分组标识不能为空');
470	    return cmdGroupHistory({ id });
471	  }
472	  if (sub === 'daily') {
473	    const flags = parseFlags(subrest, ['--id', '--from', '--to', '--tz']);
474	    if (typeof flags === 'string') return usageError(flags);
475	    const idRaw = oneFlag(flags, '--id');
476	    const fromRaw = oneFlag(flags, '--from');
477	    const toRaw = oneFlag(flags, '--to');
478	    if (idRaw === null || fromRaw === null || toRaw === null) {
479	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
480	    }
481	    const tzList = flags.get('--tz');
482	    if (tzList !== undefined && tzList.length !== 1) {
483	      return usageError("'group daily' 的 --tz 只能出现一次");
484	    }
485	    const id = idRaw.trim();
486	    if (id === '') return usageError('分组标识不能为空');
487	    const from = parseIso8601(fromRaw.trim());
488	    if (from === null) {
489	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
490	    }
491	    const to = parseIso8601(toRaw.trim());
492	    if (to === null) {
493	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
494	    }
495	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
496	    let tz: string | undefined;
497	    if (tzList !== undefined) {
498	      tz = tzList[0].trim();
499	      if (tz === '') return usageError("'--tz' 的值不能为空");
500	      const bad = checkTz(tz);
501	      if (bad !== null) return usageError(bad);
502	    }
503	    return cmdGroupDaily({ id, from, to, tz });
504	  }
505	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
506	  return usageError(`无法识别的 group 子命令 '${sub}'`);
507	}
508	
509	/**
510	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
511	 * 各恰好一个。出错返回错误消息字符串。
512	 */
513	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
514	  const segments: string[][] = [[]];
515	  for (const tok of rest) {
516	    if (tok === '--item') segments.push([]);
517	    else segments[segments.length - 1].push(tok);
518	  }
519	  const headFlags = parseFlags(segments[0], ['--request']);
520	  if (typeof headFlags === 'string') return headFlags;
521	  const requestRaw = oneFlag(headFlags, '--request');
522	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
523	  const requestId = requestRaw.trim();
524	  if (requestId === '') return '请求标识不能为空';
525	  const itemSegs = segments.slice(1);
526	  if (itemSegs.length === 0) {
527	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
528	  }
529	  const items: CorrectionItem[] = [];
530	  for (const seg of itemSegs) {
531	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
532	    if (typeof flags === 'string') return flags;
533	    const deviceRaw = oneFlag(flags, '--device');
534	    const atRaw = oneFlag(flags, '--at');
535	    const expectRaw = oneFlag(flags, '--expect');
536	    const setRaw = oneFlag(flags, '--set');
537	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
538	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
539	    }
540	    const device = deviceRaw.trim();
541	    if (device === '') return "'--device' 的值不能为空";
542	    const ts = parseIso8601(atRaw.trim());
543	    if (ts === null) {
544	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
545	    }
546	    const expectedMilli = parseKwh(expectRaw.trim());
547	    if (expectedMilli === null) {
548	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
549	    }
550	    const replacementMilli = parseKwh(setRaw.trim());
551	    if (replacementMilli === null) {
552	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
553	    }
554	    items.push({ device, ts, expectedMilli, replacementMilli });
555	  }
556	  return { requestId, items };
557	}
558	
559	function cmdCorrectEntry(rest: string[]): number {
560	  const parsed = parseCorrectItems(rest);
561	  if (typeof parsed === 'string') return usageError(parsed);
562	  return cmdCorrect(parsed.requestId, parsed.items);
563	}
564	
565	function cmdUndoEntry(rest: string[]): number {
566	  const flags = parseFlags(rest, ['--request', '--target']);
567	  if (typeof flags === 'string') return usageError(flags);
568	  const requestRaw = oneFlag(flags, '--request');
569	  const targetRaw = oneFlag(flags, '--target');
570	  if (requestRaw === null || targetRaw === null) {
571	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
572	  }
573	  const requestId = requestRaw.trim();
574	  if (requestId === '') return usageError('撤销请求标识不能为空');
575	  const targetId = targetRaw.trim();
576	  if (targetId === '') return usageError('目标修正请求标识不能为空');
577	  return cmdUndo(requestId, targetId);
578	}
579	
580	function main(args: string[]): number {
581	  // 所有入口(含无参数、--help/-h、非法参数)都先取得数据目录操作权并处理
582	  // 未完成恢复,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
583	  const result = withDirectoryCoordination<number>(() => runCommand(args));
584	  return typeof result === 'number' ? result : 1;
585	}
586	
587	function runCommand(args: string[]): number {
588	  if (args.length === 0) {
589	    console.log(help);
590	    return 0;
591	  }
592	  const [cmd, ...rest] = args;
593	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
594	    console.log(help);
595	    return 0;
596	  }
597	
598	  if (cmd === 'import') {
599	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
600	    return cmdImport(rest[0]);
601	  }
602	
603	  if (cmd === 'readings') {
604	    const parsed = parseOptions(rest);
605	    if (typeof parsed === 'string') return usageError(parsed);
606	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
607	      return usageError('查询起点必须早于终点(--from < --to)');
608	    }
609	    return cmdReadings(parsed);
610	  }
611	
612	  if (cmd === 'daily') {
613	    const parsed = parseOptions(rest, true);
614	    if (typeof parsed === 'string') return usageError(parsed);
615	    if (parsed.from === undefined || parsed.to === undefined) {
616	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
617	    }
618	    if (parsed.from >= parsed.to) {
619	      return usageError('查询起点必须早于终点(--from < --to)');
620	    }
621	    if (parsed.tz !== undefined) {
622	      const bad = checkTz(parsed.tz);
623	      if (bad !== null) return usageError(bad);
624	    }
625	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to, tz: parsed.tz });
626	  }
627	
628	  if (cmd === 'rule') return cmdRule(rest);
629	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
630	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
631	  if (cmd === 'group') return cmdGroup(rest);
632	  if (cmd === 'correct') return cmdCorrectEntry(rest);
633	  if (cmd === 'undo') return cmdUndoEntry(rest);
634	
635	  if (cmd === 'corrections') {
636	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
637	    return cmdCorrections();
638	  }
639	
640	  if (cmd === 'ack') {
641	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
642	    const alertId = rest[0].trim();
643	    if (alertId === '') return usageError('告警标识不能为空');
644	    return cmdAck(alertId);
645	  }
646	
647	  if (cmd === 'backup') {
648	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
649	    return cmdBackup(rest[0]);
650	  }
651	
652	  if (cmd === 'restore') {
653	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
654	    return cmdRestore(rest[0]);
655	  }
656	
657	  return usageError(`无法识别的参数 '${cmd}'`);
658	}
659	
660	process.exitCode = main(process.argv.slice(2));
