1	// group 子命令:分组成员版本配置、成员历史查询与分组能耗日报。
2	//
3	// - 分组以首次配置建立,标识非空唯一(去首尾空白、区分大小写);每次配置指定
4	//   生效时刻(含)与一整套已有设备,从该时刻起生效直到下一版本接替;允许乱序
5	//   补录历史版本。成员不能为空,同设备重复列出只算一次,成员顺序不影响等价性,
6	//   设备可属于多个分组。同组同一实际生效时刻、同成员集合重试成功且不新增,
7	//   异成员集合报冲突。
8	// - 配置整次成功或不提交:未知设备、冲突、损坏或不可读存储及写入失败都明确
9	//   报错并保留操作前状态。配置不改读数、规则和告警,导入也不改配置。
10	// - 日报按当地自然日切分(起点含、终点不含,首尾只统计重叠部分;默认 UTC,
11	//   可用 --tz 指定 IANA 时区,时区只决定分日),按当时生效成员计算,不把
12	//   最新成员套用到历史;首个版本生效前记为未知。各设备使用完整已存时序,
13	//   区间两端读数即使在查询范围外也参与;成员切换不需要恰好有读数,首条
14	//   读数之前、末条之后及孤立读数时段为未知,不外推。
15	// - 每个时段只有全部生效成员均处于非下降读数区间时才是有效覆盖,并计入成员
16	//   消耗之和;任一成员下降则为异常覆盖,否则任一成员未知则为未知覆盖。异常与
17	//   未知时段不计任何成员消耗,不以缺失设备为零补齐。覆盖秒数按分组实际时间
18	//   计算,不累加成员秒数。各设备片段仍以原读数区间起点累计比例向下取整,
19	//   两端累计量之差为消耗;日界线、查询边界与成员切换均不重置分摊起点,
20	//   拆开查询相加结果一致。全程 BigInt 精确计算,kWh 固定三位小数。
21	// - 日报与历史只读;读取读数时拒绝同设备同一实际时刻的多条存储记录。
22	
23	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
24	import { dirname } from 'node:path';
25	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
26	import { formatIsoUtc } from './time.ts';
27	import { localDays, loadTimezone } from './tz.ts';
28	import { formatKwh } from './value.ts';
29	
30	export interface GroupVersion {
31	  /** 生效时刻(含),epoch 秒。 */
32	  at: number;
33	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
34	  members: string[];
35	}
36	
37	export interface Group {
38	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
39	  id: string;
40	  /** 成员版本,按生效时刻升序。 */
41	  versions: GroupVersion[];
42	}
43	
44	function err(message: string): void {
45	  console.error(`meterwatch: ${message}`);
46	}
47	
48	/**
49	 * 解析分组存储的 JSON 结构。结构非法抛出 StoreError;source 用于错误消息
50	 * (如 `storage file <path>`)。
51	 */
52	export function parseGroups(data: unknown, source: string): Group[] {
53	  const bad = (what: string): StoreError =>
54	    new StoreError(`${source} is corrupted (${what})`);
55	  const o = data as Record<string, unknown>;
56	  if (o === null || typeof o !== 'object') throw bad('not an object');
57	  if (!Array.isArray(o.groups)) throw bad('missing groups array');
58	
59	  const ids = new Set<string>();
60	  const groups: Group[] = [];
61	  for (const g of o.groups as Array<Record<string, unknown>>) {
62	    const ok =
63	      g !== null &&
64	      typeof g === 'object' &&
65	      typeof g.id === 'string' &&
66	      g.id.length > 0 &&
67	      Array.isArray(g.versions) &&
68	      g.versions.length > 0;
69	    if (!ok) throw bad('invalid group entry');
70	    if (ids.has(g.id as string)) throw bad(`duplicate group id '${g.id}'`);
71	    ids.add(g.id as string);
72	
73	    const versions: GroupVersion[] = [];
74	    const seenAts = new Set<number>();
75	    for (const v of g.versions as Array<Record<string, unknown>>) {
76	      const vok =
77	        v !== null &&
78	        typeof v === 'object' &&
79	        Number.isSafeInteger(v.at) &&
80	        Array.isArray(v.members) &&
81	        v.members.length > 0 &&
82	        (v.members as unknown[]).every((m) => typeof m === 'string' && (m as string).length > 0);
83	      if (!vok) throw bad(`invalid version entry in group '${g.id}'`);
84	      const at = v.at as number;
85	      if (seenAts.has(at)) throw bad(`duplicate version time in group '${g.id}'`);
86	      seenAts.add(at);
87	      const members = [...(v.members as string[])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
88	      for (let i = 1; i < members.length; i++) {
89	        if (members[i] === members[i - 1]) {
90	          throw bad(`duplicate member '${members[i]}' in group '${g.id}'`);
91	        }
92	      }
93	      versions.push({ at, members });
94	    }
95	    versions.sort((a, b) => a.at - b.at);
96	    groups.push({ id: g.id as string, versions });
97	  }
98	  return groups;
99	}
100	
101	/** 读取分组存储;文件不存在返回空数组,存在但无法读取或内容损坏抛出 StoreError。 */
102	export function loadGroups(path: string): Group[] {
103	  let text: string;
104	  try {
105	    text = readFileSync(path, 'utf8');
106	  } catch (e) {
107	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return [];
108	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
109	  }
110	  let data: unknown;
111	  try {
112	    data = JSON.parse(text);
113	  } catch {
114	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
115	  }
116	  return parseGroups(data, `storage file ${path}`);
117	}
118	
119	/** 序列化为分组存储文件的 JSON 结构。 */
120	export function serializeGroups(groups: Group[]): Record<string, unknown> {
121	  return { version: 1, groups };
122	}
123	
124	/** 原子写入分组存储;失败抛错,原有数据保持不变。 */
125	function saveGroups(path: string, groups: Group[]): void {
126	  mkdirSync(dirname(path), { recursive: true });
127	  const tmp = `${path}.tmp-${process.pid}`;
128	  const body = JSON.stringify(serializeGroups(groups), null, 2) + '\n';
129	  try {
130	    writeFileSync(tmp, body, 'utf8');
131	    renameSync(tmp, path);
132	  } catch (e) {
133	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
134	  }
135	}
136	
137	/**
138	 * 载入读数并按设备分组,各组时序按时刻排序。
139	 * 任一设备(包括未被任何分组引用的设备)同一实际时刻存在多条存储记录时
140	 * 抛 StoreError:新功能拒绝全库重复身份,而不只是成员设备。
141	 */
142	export function loadCheckedSeriesByDevice(all: Reading[]): Map<string, Reading[]> {
143	  const byDevice = new Map<string, Reading[]>();
144	  for (const r of all) {
145	    const list = byDevice.get(r.device);
146	    if (list) list.push(r);
147	    else byDevice.set(r.device, [r]);
148	  }
149	  for (const [device, list] of byDevice) {
150	    list.sort((a, b) => a.ts - b.ts);
151	    for (let i = 1; i < list.length; i++) {
152	      if (list[i].ts === list[i - 1].ts) {
153	        throw new StoreError(
154	          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
155	        );
156	      }
157	    }
158	  }
159	  return byDevice;
160	}
161	
162	/** 在按时刻升序的时序中找最后一条 ts <= s 的下标,无则 -1。 */
163	function floorIndex(series: Reading[], s: number): number {
164	  let lo = 0;
165	  let hi = series.length - 1;
166	  let ans = -1;
167	  while (lo <= hi) {
168	    const mid = (lo + hi) >> 1;
169	    if (series[mid].ts <= s) {
170	      ans = mid;
171	      lo = mid + 1;
172	    } else {
173	      hi = mid - 1;
174	    }
175	  }
176	  return ans;
177	}
178	
179	type SliceKind = 'valid' | 'anomaly' | 'unknown';
180	
181	/**
182	 * 单设备在片段 [s, e) 上的状态与消耗。片段完全落在同一读数区间内
183	 * (调用方保证切点包含区间内全部读数时刻)。非下降区间以区间起点累计
184	 * 比例向下取整,消耗为两端累计量之差;下降区间为异常;首条读数之前、
185	 * 末条之后及孤立读数时段为未知,不外推。
186	 */
187	function deviceSlice(
188	  series: Reading[],
189	  s: number,
190	  e: number,
191	): { kind: SliceKind; consumption: bigint } {
192	  const i = floorIndex(series, s);
193	  if (i < 0 || i + 1 >= series.length) return { kind: 'unknown', consumption: 0n };
194	  const a = series[i];
195	  const b = series[i + 1];
196	  const diff = b.milli - a.milli;
197	  if (diff < 0n) return { kind: 'anomaly', consumption: 0n };
198	  const duration = BigInt(b.ts - a.ts);
199	  const cumulative = (t: number): bigint => (diff * BigInt(t - a.ts)) / duration;
200	  return { kind: 'valid', consumption: cumulative(e) - cumulative(s) };
201	}
202	
203	export interface GroupPeriod {
204	  /** 时段起点(含),epoch 秒。 */
205	  start: number;
206	  /** 时段终点(不含),epoch 秒。 */
207	  end: number;
208	  /** 该时段生效成员;null 表示首个版本生效前(未知)。 */
209	  members: string[] | null;
210	}
211	
212	export interface GroupSegmentStats {
213	  /** 有效(全部成员非下降)覆盖秒数,按分组实际时间计。 */
214	  valid: number;
215	  /** 异常(任一成员下降)覆盖秒数。 */
216	  anomaly: number;
217	  /** 未知(无生效版本或任一成员未知)覆盖秒数。 */
218	  unknown: number;
219	  /** 有效时段内全部生效成员的分摊消耗之和,毫千瓦时 BigInt。 */
220	  consumption: bigint;
221	  /** 段内按生效时刻切分的成员时段。 */
222	  periods: GroupPeriod[];
223	}
224	
225	/**
226	 * 计算分组在 [segStart, segEnd) 上的覆盖与消耗。
227	 * versions 按生效时刻升序;seriesByDevice 含全部版本成员的完整时序。
228	 */
229	export function computeGroupSegment(
230	  versions: GroupVersion[],
231	  seriesByDevice: Map<string, Reading[]>,
232	  segStart: number,
233	  segEnd: number,
234	): GroupSegmentStats {
235	  // 按版本生效时刻把段切成成员恒定的时段;首个版本生效前 members 为 null。
236	  const periods: GroupPeriod[] = [];
237	  let idx = -1;
238	  for (let i = 0; i < versions.length; i++) {
239	    if (versions[i].at <= segStart) idx = i;
240	    else break;
241	  }
242	  let cursor = segStart;
243	  while (cursor < segEnd) {
244	    const nextAt = idx + 1 < versions.length ? versions[idx + 1].at : Number.POSITIVE_INFINITY;
245	    const pEnd = Math.min(segEnd, nextAt);
246	    periods.push({ start: cursor, end: pEnd, members: idx >= 0 ? versions[idx].members : null });
247	    cursor = pEnd;
248	    idx++;
249	  }
250	
251	  let valid = 0;
252	  let anomaly = 0;
253	  let unknown = 0;
254	  let consumption = 0n;
255	  for (const p of periods) {
256	    if (p.members === null) {
257	      unknown += p.end - p.start;
258	      continue;
259	    }
260	    // 切点:时段边界与全部成员的读数时刻;相邻切点间每个成员的状态恒定。
261	    const bounds = new Set<number>([p.start, p.end]);
262	    for (const m of p.members) {
263	      for (const r of seriesByDevice.get(m) ?? []) {
264	        if (r.ts > p.start && r.ts < p.end) bounds.add(r.ts);
265	      }
266	    }
267	    const sorted = [...bounds].sort((a, b) => a - b);
268	    for (let k = 0; k + 1 < sorted.length; k++) {
269	      const s = sorted[k];
270	      const e = sorted[k + 1];
271	      let anyAnomaly = false;
272	      let anyUnknown = false;
273	      let slice = 0n;
274	      for (const m of p.members) {
275	        const res = deviceSlice(seriesByDevice.get(m) ?? [], s, e);
276	        if (res.kind === 'anomaly') anyAnomaly = true;
277	        else if (res.kind === 'unknown') anyUnknown = true;
278	        else slice += res.consumption;
279	      }
280	      if (anyAnomaly) {
281	        anomaly += e - s;
282	      } else if (anyUnknown) {
283	        unknown += e - s;
284	      } else {
285	        valid += e - s;
286	        consumption += slice;
287	      }
288	    }
289	  }
290	  return { valid, anomaly, unknown, consumption, periods };
291	}
292	
293	/**
294	 * 配置分组成员版本。首次配置即建立分组;同组同一实际生效时刻、同成员集合
295	 * 重试成功且不新增,异成员集合报冲突。整次成功或不提交。返回进程退出码。
296	 */
297	export function cmdGroupConfigure(opts: { id: string; at: number; members: string[] }): number {
298	  const path = groupFilePath();
299	  let groups: Group[];
300	  try {
301	    groups = loadGroups(path);
302	  } catch (e) {
303	    if (e instanceof StoreError) {
304	      err(e.message);
305	      return 1;
306	    }
307	    throw e;
308	  }
309	
310	  // 规范形:同设备重复列出只算一次,成员顺序不影响等价性。
311	  const members = [...new Set(opts.members)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
312	
313	  let known: Set<string>;
314	  try {
315	    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
316	  } catch (e) {
317	    if (e instanceof StoreError) {
318	      err(e.message);
319	      return 1;
320	    }
321	    throw e;
322	  }
323	  for (const m of members) {
324	    if (!known.has(m)) {
325	      err(`unknown device '${m}': no stored readings; import readings before configuring a group`);
326	      return 1;
327	    }
328	  }
329	
330	  const existing = groups.find((g) => g.id === opts.id);
331	  if (existing) {
332	    const v = existing.versions.find((ver) => ver.at === opts.at);
333	    if (v) {
334	      const same =
335	        v.members.length === members.length && v.members.every((m, i) => m === members[i]);
336	      if (same) {
337	        console.log(
338	          `group '${opts.id}' already has an identical member version at ${formatIsoUtc(opts.at)}; unchanged`,
339	        );
340	        return 0;
341	      }
342	      err(
343	        `group '${opts.id}' already has a different member version at ${formatIsoUtc(opts.at)} ` +
344	          `(stored members=${v.members.join(',')}, got members=${members.join(',')}); conflict`,
345	      );
346	      return 1;
347	    }
348	    existing.versions.push({ at: opts.at, members });
349	    existing.versions.sort((a, b) => a.at - b.at);
350	  } else {
351	    groups.push({ id: opts.id, versions: [{ at: opts.at, members }] });
352	  }
353	
354	  try {
355	    saveGroups(path, groups);
356	  } catch (e) {
357	    if (e instanceof StoreError) {
358	      err(e.message);
359	      return 1;
360	    }
361	    throw e;
362	  }
363	  console.log(
364	    `group '${opts.id}' configured: members=${members.join(',')} effective ${formatIsoUtc(opts.at)}`,
365	  );
366	  return 0;
367	}
368	
369	/** 查看分组成员版本历史,按生效时刻排序。只读。返回进程退出码。 */
370	export function cmdGroupHistory(opts: { id: string }): number {
371	  let groups: Group[];
372	  try {
373	    groups = loadGroups(groupFilePath());
374	  } catch (e) {
375	    if (e instanceof StoreError) {
376	      err(e.message);
377	      return 1;
378	    }
379	    throw e;
380	  }
381	  const group = groups.find((g) => g.id === opts.id);
382	  if (!group) {
383	    err(`unknown group '${opts.id}'`);
384	    return 1;
385	  }
386	  console.log(`group: ${group.id}`);
387	  for (const v of group.versions) {
388	    console.log(`  ${formatIsoUtc(v.at)}  members=${v.members.join(',')}`);
389	  }
390	  return 0;
391	}
392	
393	/**
394	 * 分组能耗日报:按当地自然日切分(默认 UTC,--tz 指定 IANA 时区),按当时
395	 * 生效成员计算。只读,不写入数据。返回进程退出码。
396	 */
397	export function cmdGroupDaily(opts: { id: string; from: number; to: number; tz?: string }): number {
398	  const tzName = opts.tz ?? 'UTC';
399	  const tz = loadTimezone(tzName);
400	  if (!tz) {
401	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
402	    return 2;
403	  }
404	
405	  let groups: Group[];
406	  try {
407	    groups = loadGroups(groupFilePath());
408	  } catch (e) {
409	    if (e instanceof StoreError) {
410	      err(e.message);
411	      return 1;
412	    }
413	    throw e;
414	  }
415	  const group = groups.find((g) => g.id === opts.id);
416	  if (!group) {
417	    err(`unknown group '${opts.id}'`);
418	    return 1;
419	  }
420	
421	  let seriesByDevice: Map<string, Reading[]>;
422	  try {
423	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
424	  } catch (e) {
425	    if (e instanceof StoreError) {
426	      err(e.message);
427	      return 1;
428	    }
429	    throw e;
430	  }
431	
432	  const days = localDays(tz, opts.from, opts.to);
433	
434	  console.log(`group: ${group.id}`);
435	  console.log(`timezone: ${tzName}`);
436	  let total = 0n;
437	  let computedDays = 0;
438	  let incomplete = false;
439	  for (const day of days) {
440	    let valid = 0;
441	    let anomaly = 0;
442	    let unknown = 0;
443	    let consumption = 0n;
444	    const periods: GroupPeriod[] = [];
445	    for (const p of day.periods) {
446	      const stats = computeGroupSegment(group.versions, seriesByDevice, p.start, p.end);
447	      valid += stats.valid;
448	      anomaly += stats.anomaly;
449	      unknown += stats.unknown;
450	      consumption += stats.consumption;
451	      periods.push(...stats.periods);
452	    }
453	    const dayIncomplete = anomaly > 0 || unknown > 0;
454	    if (dayIncomplete) incomplete = true;
455	
456	    let consumptionText: string;
457	    if (valid > 0) {
458	      consumptionText = `consumption=${formatKwh(consumption)} kWh (estimate)`;
459	      total += consumption;
460	      computedDays++;
461	    } else {
462	      consumptionText = 'consumption=n/a (no valid coverage)';
463	    }
464	    let line =
465	      `  ${day.label}  ${consumptionText}` +
466	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
467	    if (dayIncomplete) line += '  INCOMPLETE';
468	    console.log(line);
469	    for (const p of day.periods) {
470	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
471	    }
472	    for (const p of periods) {
473	      const members = p.members === null ? '(no version in effect)' : p.members.join(',');
474	      console.log(
475	        `    members=${members}  period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`,
476	      );
477	    }
478	  }
479	
480	  const totalText =
481	    computedDays > 0
482	      ? `total consumption=${formatKwh(total)} kWh (estimate)`
483	      : 'total consumption=n/a (no valid coverage)';
484	  const status = incomplete
485	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
486	    : 'status=complete';
487	  console.log(
488	    `  summary: group=${group.id}  computed=${computedDays}/${days.length} day(s)  ${totalText}  ${status}`,
489	  );
490	  return 0;
491	}
