35	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
36	import { dirname } from 'node:path';
37	import {
38	  alertFilePath,
39	  dataFilePath,
40	  groupFilePath,
41	  loadStore,
42	  parseStoredMilli,
43	  StoreError,
44	  type Reading,
45	} from './store.ts';
46	import { computeDay, DAY_SECONDS, type DayStats } from './report.ts';
47	import { computeGroupSegment, loadCheckedSeriesByDevice, loadGroups, type Group } from './groups.ts';
48	import { formatIsoUtc, parseUtcDate } from './time.ts';
49	import { canonicalTimezone, loadTimezone, localDateRange, type LocalDay } from './tz.ts';
50	import { formatKwh } from './value.ts';
51	
52	export type RuleTargetType = 'device' | 'group';
53	
54	export interface AlertRule {
55	  /** 规则标识(非空、唯一,已去首尾空白,设备与分组规则间统一唯一)。 */
56	  id: string;
57	  /** 目标类型:设备或分组。 */
58	  targetType: RuleTargetType;
59	  /** 绑定的设备或分组标识(已去首尾空白,区分大小写),创建后固定。 */
60	  targetId: string;
61	  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
62	  thresholdMilli: bigint;
63	  /** 评估时区,运行环境解析后的规范 IANA 名(省略为 UTC),创建后固定。 */
64	  tz: string;
65	}
66	
67	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
68	
69	export interface AlertEvent {
70	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
71	  seq: number;
72	  type: AlertEventType;
73	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
74	  consumptionMilli?: string;
75	}
76	
77	export interface AlertRecord {
78	  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
79	  id: string;
80	  ruleId: string;
81	  /** 规则时区下的当地日期,YYYY-MM-DD(UTC 规则即 UTC 日期)。 */
82	  date: string;
83	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
84	  status: 'triggered' | 'recovered';
85	  acknowledged: boolean;
86	  events: AlertEvent[];
87	}
88	
89	export interface AlertState {
90	  nextAlertNum: number;
91	  nextEventSeq: number;
92	  rules: AlertRule[];
93	  alerts: AlertRecord[];
94	}
95	
96	function err(message: string): void {
97	  console.error(`meterwatch: ${message}`);
98	}
99	
100	function emptyState(): AlertState {
101	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
102	}
103	
104	/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
105	function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
106	  return `${rule.targetType}=${rule.targetId}`;
107	}
108	
109	/**
110	 * 解析告警存储的 JSON 结构。结构非法抛出 StoreError;source 用于错误消息
111	 * (如 `storage file <path>`)。旧版仅含 device 字段、无时区的规则按 UTC 读入。
112	 */
113	export function parseAlertState(data: unknown, source: string): AlertState {
114	  const bad = (what: string): StoreError =>
115	    new StoreError(`${source} is corrupted (${what})`);
116	  const o = data as Record<string, unknown>;
117	  if (o === null || typeof o !== 'object') throw bad('not an object');
118	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
119	    throw bad('invalid nextAlertNum');
120	  }
121	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
122	    throw bad('invalid nextEventSeq');
123	  }
124	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
125	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
126	
127	  const ruleIds = new Set<string>();
128	  const rules: AlertRule[] = [];
129	  for (const r of o.rules as Array<Record<string, unknown>>) {
130	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
131	    // 按损坏数据拒绝,不猜测原值。
132	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
133	    if (
134	      r === null ||
135	      typeof r !== 'object' ||
136	      typeof r.id !== 'string' ||
137	      r.id.length === 0 ||
138	      thresholdMilli === null
139	    ) {
140	      throw bad('invalid rule entry');
141	    }
142	    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
143	    // 读入,已有设备规则无需手工转换即可继续使用。
144	    let targetType: RuleTargetType;
145	    let targetId: string;
146	    if (r.targetType === undefined) {
147	      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
148	      targetType = 'device';
149	      targetId = r.device;
150	    } else {
151	      if (r.targetType !== 'device' && r.targetType !== 'group') {
152	        throw bad(`invalid targetType in rule '${r.id}'`);
153	      }
154	      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
155	        throw bad(`invalid targetId in rule '${r.id}'`);
156	      }
157	      targetType = r.targetType;
158	      targetId = r.targetId;
159	    }
160	    // 时区:新版字段 tz 存规范 IANA 名;旧版无时区的规则按 UTC 使用。存储内
161	    // 非法时区按损坏数据拒绝,不能回退为 UTC;合法写法统一解析为规范名。
162	    let tz = 'UTC';
163	    if (r.tz !== undefined) {
164	      if (typeof r.tz !== 'string' || r.tz.length === 0) {
165	        throw bad(`invalid timezone in rule '${r.id}'`);
166	      }
167	      const canonical = canonicalTimezone(r.tz);
168	      if (canonical === null) throw bad(`invalid timezone in rule '${r.id}'`);
169	      tz = canonical;
170	    }
171	    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
172	    ruleIds.add(r.id);
173	    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint, tz });
174	  }
175	
176	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
177	  const alertIds = new Set<string>();
178	  for (const a of o.alerts as Array<Record<string, unknown>>) {
179	    const ok =
180	      a !== null &&
181	      typeof a === 'object' &&
182	      typeof a.id === 'string' &&
183	      a.id.length > 0 &&
184	      typeof a.ruleId === 'string' &&
185	      ruleIds.has(a.ruleId) &&
186	      typeof a.date === 'string' &&
187	      DATE_RE.test(a.date) &&
188	      (a.status === 'triggered' || a.status === 'recovered') &&
189	      typeof a.acknowledged === 'boolean' &&
190	      Array.isArray(a.events) &&
191	      (a.events as unknown[]).length > 0;
192	    if (!ok) throw bad('invalid alert entry');
193	    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
194	    alertIds.add(a.id);
195	    const seqs = new Set<number>();
196	    for (const e of a.events as Array<Record<string, unknown>>) {
197	      const eok =
198	        e !== null &&
199	        typeof e === 'object' &&
200	        Number.isSafeInteger(e.seq) &&
201	        (e.seq as number) >= 1 &&
202	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
203	        (e.consumptionMilli === undefined ||
204	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
205	      if (!eok) throw bad('invalid alert event');
206	      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
207	      seqs.add(e.seq as number);
208	    }
209	  }
210	  return {
211	    nextAlertNum: o.nextAlertNum as number,
212	    nextEventSeq: o.nextEventSeq as number,
213	    rules,
214	    alerts: o.alerts as unknown as AlertRecord[],
215	  };
216	}
