218	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
219	export function loadAlertState(path: string): AlertState {
220	  let text: string;
221	  try {
222	    text = readFileSync(path, 'utf8');
223	  } catch (e) {
224	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
225	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
226	  }
227	  let data: unknown;
228	  try {
229	    data = JSON.parse(text);
230	  } catch {
231	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
232	  }
233	  return parseAlertState(data, `storage file ${path}`);
234	}
235	
236	/** 序列化为告警存储文件的 JSON 结构(阈值为十进制字符串,任意大数精确)。 */
237	export function serializeAlertState(state: AlertState): Record<string, unknown> {
238	  return {
239	    version: 2,
240	    ...state,
241	    rules: state.rules.map((r) => ({
242	      id: r.id,
243	      targetType: r.targetType,
244	      targetId: r.targetId,
245	      thresholdMilli: r.thresholdMilli.toString(),
246	      tz: r.tz,
247	    })),
248	  };
249	}
250	
251	/**
252	 * 原子写入告警存储;失败抛错,原有数据保持不变。
253	 * 告警写入不触碰读数与成员版本文件。
254	 */
255	function saveAlertState(path: string, state: AlertState): void {
256	  mkdirSync(dirname(path), { recursive: true });
257	  const tmp = `${path}.tmp-${process.pid}`;
258	  const body = JSON.stringify(serializeAlertState(state), null, 2) + '\n';
259	  try {
260	    writeFileSync(tmp, body, 'utf8');
261	    renameSync(tmp, path);
262	  } catch (e) {
263	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
264	  }
265	}
266	
267	/**
268	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
269	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
270	 */
271	function deviceSeries(device: string): Reading[] {
272	  const all = loadStore(dataFilePath());
273	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
274	  for (let i = 1; i < series.length; i++) {
275	    if (series[i].ts === series[i - 1].ts) {
276	      throw new StoreError(
277	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
278	      );
279	    }
280	  }
281	  return series;
282	}
283	
284	/**
285	 * 分组规则的评估环境:绑定分组与全库设备时序。
286	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
287	 */
288	interface GroupEnv {
289	  kind: 'group';
290	  group: Group;
291	  byDevice: Map<string, Reading[]>;
292	}
293	
294	interface DeviceEnv {
295	  kind: 'device';
296	  series: Reading[];
297	}
298	
299	type RuleEnv = DeviceEnv | GroupEnv;
300	
301	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
302	function prepareEnv(rule: AlertRule): RuleEnv {
303	  if (rule.targetType === 'device') {
304	    return { kind: 'device', series: deviceSeries(rule.targetId) };
305	  }
306	  const groups = loadGroups(groupFilePath());
307	  const group = groups.find((g) => g.id === rule.targetId);
308	  if (!group) {
309	    throw new StoreError(
310	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
311	    );
312	  }
313	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
314	  return { kind: 'group', group, byDevice };
315	}
316	
317	/** 一天的有效/异常/未知覆盖秒数后缀。 */
318	function coverageSuffix(stats: Pick<DayStats, 'valid' | 'anomaly' | 'unknown'>): string {
319	  return `valid=${stats.valid}s anomaly=${stats.anomaly}s unknown=${stats.unknown}s`;
320	}
321	
322	/** 一天各实际 UTC 时段的展示行(时段按实际时刻升序)。 */
323	function periodLines(day: LocalDay): string[] {
324	  return day.periods.map((p) => `    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
325	}
326	
327	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
328	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
329	  const fmt = loadTimezone(rule.tz);
330	  if (fmt === null) {
331	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
332	  }
333	  return fmt;
334	}
335	
336	/**
337	 * 计算规则在一个当地日期上的统计:汇总归属该日期的全部实际 UTC 时段。
338	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
339	 * 日界线与成员切换都不重置各设备原读数区间的分摊起点。
340	 */
341	function computeRuleDay(env: RuleEnv, day: LocalDay): DayStats {
342	  let valid = 0;
343	  let anomaly = 0;
344	  let unknown = 0;
345	  let consumption = 0n;
346	  for (const p of day.periods) {
347	    if (env.kind === 'device') {
348	      const s = computeDay(env.series, p.start, p.end);
349	      valid += s.valid;
350	      anomaly += s.anomaly;
351	      unknown += s.unknown;
352	      consumption += s.consumption;
353	    } else {
354	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end);
355	      valid += s.valid;
356	      anomaly += s.anomaly;
357	      unknown += s.unknown;
358	      consumption += s.consumption;
359	    }
360	  }
361	  return { valid, anomaly, unknown, consumption };
362	}
363	
364	/**
365	 * 创建规则。相同标识、同目标类型、同目标标识、等价阈值及同时区(规范名)
366	 * 重试成功且不重复创建;任一不同即报冲突。设备必须已有存储读数;分组必须
367	 * 已配置。返回进程退出码。
368	 */
369	export function cmdRuleCreate(opts: {
370	  id: string;
371	  targetType: RuleTargetType;
372	  targetId: string;
373	  thresholdMilli: bigint;
374	  /** 规范 IANA 时区名(调用方已解析;省略时传 'UTC')。 */
375	  tz: string;
376	}): number {
377	  const statePath = alertFilePath();
378	  let state: AlertState;
379	  try {
380	    state = loadAlertState(statePath);
381	  } catch (e) {
382	    if (e instanceof StoreError) {
383	      err(e.message);
384	      return 1;
385	    }
386	    throw e;
387	  }
388	
389	  const got = `${opts.targetType}=${opts.targetId}`;
390	  const existing = state.rules.find((r) => r.id === opts.id);
391	  if (existing) {
392	    if (
393	      existing.targetType === opts.targetType &&
394	      existing.targetId === opts.targetId &&
395	      existing.thresholdMilli === opts.thresholdMilli &&
396	      existing.tz === opts.tz
397	    ) {
398	      console.log(
399	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
400	          `threshold=${formatKwh(existing.thresholdMilli)} kWh tz=${existing.tz}); unchanged`,
401	      );
402	      return 0;
403	    }
404	    err(
405	      `rule '${opts.id}' already exists with different parameters ` +
406	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh ` +
407	        `tz=${existing.tz}, got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
408	        `tz=${opts.tz}); conflict`,
409	    );
410	    return 1;
411	  }
412	
413	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
414	  try {
415	    if (opts.targetType === 'device') {
416	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
417	      if (!devices.has(opts.targetId)) {
418	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
419	        return 1;
420	      }
421	    } else {
422	      const groups = loadGroups(groupFilePath());
423	      if (!groups.some((g) => g.id === opts.targetId)) {
424	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
425	        return 1;
426	      }
427	    }
428	  } catch (e) {
429	    if (e instanceof StoreError) {
430	      err(e.message);
431	      return 1;
432	    }
433	    throw e;
434	  }
435	
436	  state.rules.push({
437	    id: opts.id,
438	    targetType: opts.targetType,
439	    targetId: opts.targetId,
440	    thresholdMilli: opts.thresholdMilli,
441	    tz: opts.tz,
442	  });
443	  try {
444	    saveAlertState(statePath, state);
445	  } catch (e) {
446	    if (e instanceof StoreError) {
447	      err(e.message);
448	      return 1;
449	    }
450	    throw e;
451	  }
452	  console.log(
453	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh tz=${opts.tz}`,
454	  );
455	  return 0;
456	}
457	
458	/** 列出全部规则(含目标类型与时区)。只读。返回进程退出码。 */
459	export function cmdRuleList(): number {
460	  let state: AlertState;
461	  try {
462	    state = loadAlertState(alertFilePath());
463	  } catch (e) {
464	    if (e instanceof StoreError) {
465	      err(e.message);
466	      return 1;
467	    }
468	    throw e;
469	  }
470	  if (state.rules.length === 0) {
471	    console.log('no rules defined');
472	    return 0;
473	  }
474	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
475	  for (const r of rules) {
476	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
477	    console.log(
478	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  ` +
479	        `tz=${r.tz}  open alerts=${open}`,
480	    );
481	  }
482	  return 0;
483	}
484	
485	/**
486	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
487	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
488	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
489	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
490	 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
491	 */
492	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
493	  const statePath = alertFilePath();
494	  let state: AlertState;
495	  let rule: AlertRule;
496	  let env: RuleEnv;
497	  let fmt: Intl.DateTimeFormat;
498	  try {
499	    state = loadAlertState(statePath);
500	    const found = state.rules.find((r) => r.id === opts.ruleId);
501	    if (!found) {
502	      err(`unknown rule '${opts.ruleId}'`);
503	      return 1;
504	    }
505	    rule = found;
506	    env = prepareEnv(rule);
507	    fmt = ruleFormat(rule);
508	  } catch (e) {
509	    if (e instanceof StoreError) {
510	      err(e.message);
511	      return 1;
512	    }
513	    throw e;
514	  }
515	
516	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
517	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
518	  const alertIds = new Set(state.alerts.map((a) => a.id));
519	
520	  const threshold = rule.thresholdMilli;
521	  const lines: string[] = [];
522	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
523	    if (day === null) {
524	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
525	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
526	      continue;
527	    }
528	    const stats = computeRuleDay(env, day);
529	    const coverage = coverageSuffix(stats);
530	    if (stats.unknown > 0 || stats.anomaly > 0) {
531	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
532	      lines.push(`  ${label}  undecidable (${coverage})  no alert action`);
533	      lines.push(...periodLines(day));
534	      continue;
535	    }
536	    const exceeded = stats.consumption > threshold;
537	    const cmp =
538	      `consumption=${formatKwh(stats.consumption)} kWh ` +
539	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
540	    const open = state.alerts.find(
541	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
542	    );
543	    if (exceeded) {
544	      if (open) {
545	        // 重复超限:保留原标识,不新增事件。
546	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
547	      } else {
548	        const id = `alert-${state.nextAlertNum++}`;
549	        if (alertIds.has(id)) {
550	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
551	          return 1;
552	        }
553	        alertIds.add(id);
554	        state.alerts.push({
555	          id,
556	          ruleId: rule.id,
557	          date: label,
558	          status: 'triggered',
559	          acknowledged: false,
560	          events: [
561	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
562	          ],
563	        });
564	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
565	      }
566	    } else {
567	      if (open) {
568	        open.status = 'recovered';
569	        open.events.push({
570	          seq: state.nextEventSeq++,
571	          type: 'recovered',
572	          consumptionMilli: stats.consumption.toString(),
573	        });
574	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
575	      } else {
576	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
577	      }
578	    }
579	    lines.push(...periodLines(day));
580	  }
581	
582	  try {
583	    saveAlertState(statePath, state);
584	  } catch (e) {
585	    if (e instanceof StoreError) {
586	      err(e.message);
587	      return 1;
588	    }
589	    throw e;
590	  }
591	
592	  console.log(
593	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  tz=${rule.tz}`,
594	  );
595	  for (const line of lines) console.log(line);
596	  return 0;
597	}
598	
599	/**
600	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
601	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
602	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
603	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
604	 */
605	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
606	  let state: AlertState;
607	  let rule: AlertRule;
608	  let env: RuleEnv;
609	  let fmt: Intl.DateTimeFormat;
610	  try {
611	    state = loadAlertState(alertFilePath());
612	    const found = state.rules.find((r) => r.id === opts.ruleId);
613	    if (!found) {
614	      err(`unknown rule '${opts.ruleId}'`);
615	      return 1;
616	    }
617	    rule = found;
618	    env = prepareEnv(rule);
619	    fmt = ruleFormat(rule);
620	  } catch (e) {
621	    if (e instanceof StoreError) {
622	      err(e.message);
623	      return 1;
624	    }
625	    throw e;
626	  }
627	
628	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
629	  // 记录的全部日期。
630	  let labels: string[];
631	  if (opts.from !== undefined && opts.to !== undefined) {
632	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
633	  } else {
634	    labels = [
635	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
636	    ].sort();
637	  }
638	
639	  console.log(
640	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  tz=${rule.tz}`,
641	  );
642	  if (labels.length === 0) {
643	    console.log(`  no alerts recorded for rule '${rule.id}'`);
644	    return 0;
645	  }
646	
647	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
648	  // 末日后延一天作为切分终点。
649	  const last = parseUtcDate(labels[labels.length - 1]) as number;
650	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
651	  const byLabel = new Map<string, LocalDay | null>();
652	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
653	
654	  const threshold = rule.thresholdMilli;
655	  for (const label of labels) {
656	    const day = byLabel.get(label) ?? null;
657	    if (day === null) {
658	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
659	    } else {
660	      const stats = computeRuleDay(env, day);
661	      if (stats.unknown > 0 || stats.anomaly > 0) {
662	        console.log(`  ${label}  undecidable (${coverageSuffix(stats)})`);
663	      } else {
664	        const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
665	        console.log(
666	          `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
667	            `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats)}`,
668	        );
669	      }
670	      for (const line of periodLines(day)) console.log(line);
671	    }
672	    const alerts = state.alerts
673	      .filter((a) => a.ruleId === rule.id && a.date === label)
674	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
675	    if (alerts.length === 0) {
676	      console.log('    no alerts');
677	      continue;
678	    }
679	    for (const a of alerts) {
680	      console.log(
681	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
682	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
683	      );
684	      const events = a.events
685	        .map((e) => {
686	          const consumption =
687	            e.consumptionMilli !== undefined
688	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
689	              : '';
690	          return `#${e.seq} ${e.type}${consumption}`;
691	        })
692	        .join(', ');
693	      console.log(`      events: ${events}`);
694	    }
695	  }
696	  return 0;
697	}
698	
699	/**
700	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
701	 * 确认不改变超限或恢复状态。返回进程退出码。
702	 */
703	export function cmdAck(alertId: string): number {
704	  const statePath = alertFilePath();
705	  let state: AlertState;
706	  try {
707	    state = loadAlertState(statePath);
708	  } catch (e) {
709	    if (e instanceof StoreError) {
710	      err(e.message);
711	      return 1;
712	    }
713	    throw e;
714	  }
715	  const alert = state.alerts.find((a) => a.id === alertId);
716	  if (!alert) {
717	    err(`unknown alert '${alertId}'`);
718	    return 1;
719	  }
720	  if (alert.acknowledged) {
721	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
722	    return 0;
723	  }
724	  alert.acknowledged = true;
725	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
726	  try {
727	    saveAlertState(statePath, state);
728	  } catch (e) {
729	    if (e instanceof StoreError) {
730	      err(e.message);
731	      return 1;
732	    }
733	    throw e;
734	  }
735	  const rule = state.rules.find((r) => r.id === alert.ruleId);
736	  const target = rule ? ` ${targetLabel(rule)}` : '';
737	  console.log(
738	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
739	  );
740	  return 0;
741	}
742

