  valid: number;
  /** 异常(下降区间)覆盖秒数。 */
  anomaly: number;
  /** 未知(无区间覆盖或区间超过采样间隔限制)秒数。 */
  unknown: number;
  /** unknown 中由超过采样间隔限制的相邻区间造成的秒数(子集,单独区分显示)。 */
  gapUnknown: number;
  /** 与统计范围相交的过长区间明细(原始相邻读数时刻),已去重。 */
  gaps: GapDetail[];
