/** 合并过长区间明细,按设备、起点、终点去重(保持首次出现顺序)。 */
export function mergeGaps(into: GapDetail[], add: GapDetail[]): void {
  const seen = new Set(into.map((g) => `${g.device ?? ''} ${g.start} ${g.end}`));
  for (const g of add) {
    const key = `${g.device ?? ''} ${g.start} ${g.end}`;
    if (!seen.has(key)) {
      seen.add(key);
      into.push(g);
    }
